    AS expected(signature text,args text,returns text) LOOP
    v_oid := to_regprocedure(e.signature);
    IF v_oid IS NOT NULL AND
      (pg_get_function_identity_arguments(v_oid) IS DISTINCT FROM e.args
       OR pg_get_function_result(v_oid) IS DISTINCT FROM e.returns) THEN
      EXECUTE format('DROP FUNCTION %s RESTRICT',e.signature);
      RAISE NOTICE 'CI contract restore: %',e.signature;
    END IF;
  END LOOP;
END $contracts$;
